// Fixtures generated by the Rust implementation (merkle + Ed25519 signature),
// so the browser verifier is pinned to the real chain, not to itself.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import '../blake3.js';
import '../coverage.js';

const ENTRY = '02' + '02'.repeat(31);
const ROOT = '43a6d5dbd0de0465962875699e1f072611c2d4a5f3c1d23d4703848a1ef31c71';
const SIGNER = '6e7a1cdd29b0b78fd13af4c5598feff4ef2a97166e3ca6f2e4fbfccd80505bf1';
const SIGNATURE =
  '4ebdb9298a5f2d04403db79838a2d352a9bac525c7f88556cd2e386ed0c96354' +
  'b140df12b2bb74318a1666640ccfbb92b0a47af5f20cd97a4dbbfe87231ff109';
const SIBLINGS = [
  '9515049071ed913149a80d3bb7891fcd4c6c1e3d14ad878939a80f9b9a91e08c',
  'f51c4f4da841f85464e4f30a919d0a7a242296b37ff8fa72eb15ce9404d6441b',
];
const BODY_B64 = '';

function witness(overrides = {}) {
  return {
    signer: SIGNER,
    entry_ids_root: ROOT,
    entries_count: 3,
    body_b64: BODY_B64,
    signature: SIGNATURE,
    proof: { entry_id: ENTRY, index: 1, count: 3, siblings: SIBLINGS },
    ...overrides,
  };
}

test('a Rust-generated witness verifies locally: merkle path + Ed25519', async () => {
  const result = await datuCoverage.verifyWitness(ENTRY, witness());
  assert.equal(result.ok, true, JSON.stringify(result));
  assert.equal(result.signature, 'ok');
});

test('a tampered sibling no longer reaches the signed root', async () => {
  const bad = witness();
  bad.proof = { ...bad.proof, siblings: ['00' + SIBLINGS[0].slice(2), SIBLINGS[1]] };
  const result = await datuCoverage.verifyWitness(ENTRY, bad);
  assert.equal(result.ok, false);
  assert.match(result.reason, /merkle path/);
});

test('a different entry cannot ride the same path', async () => {
  const other = '03' + '03'.repeat(31);
  const bad = witness();
  bad.proof = { ...bad.proof, entry_id: other };
  const result = await datuCoverage.verifyWitness(other, bad);
  assert.equal(result.ok, false);
});

test('a tampered checkpoint signature is reported', async () => {
  const bad = witness();
  bad.signature = (SIGNATURE[0] === 'f' ? 'e' : 'f') + SIGNATURE.slice(1);
  const result = await datuCoverage.verifyWitness(ENTRY, bad);
  assert.equal(result.ok, false);
  assert.match(result.reason, /signature/);
});

test('a body swapped under the same signature is reported', async () => {
  const bad = witness();
  const bytes = Uint8Array.from(atob(BODY_B64), (c) => c.charCodeAt(0));
  bytes[bytes.length - 1] ^= 0xff;
  bad.body_b64 = btoa(String.fromCharCode(...bytes));
  const result = await datuCoverage.verifyWitness(ENTRY, bad);
  assert.equal(result.ok, false);
  assert.match(result.reason, /signature/);
});
